using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ImageWorkspaceOperations
{
    public Settings workflow_window(Control owner,string title,Vector2 minimum)
    {
        var popup=new PopupPanel();popup.AddThemeStyleboxOverride("panel",box(new Color("111c28"),new Color("426879"),12,14));owner.AddChild(popup);var column=new VBoxContainer{CustomMinimumSize=minimum};column.AddThemeConstantOverride("separation",10);popup.AddChild(column);var header=new HBoxContainer();column.AddChild(header);var heading=new Label{Text=title.ToUpperInvariant(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};heading.AddThemeFontSizeOverride("font_size",18);heading.AddThemeColorOverride("font_color",new Color("77e4c7"));header.AddChild(heading);button(owner,header,"×",Callable.From(popup.QueueFree),"Close","");popup.PopupHide+=popup.QueueFree;return new Settings{["popup"]=popup,["body"]=column};
    }
    public VBoxContainer panel_card(Control parent,string title,string subtitle)
    {
        var panel=new PanelContainer();panel.AddThemeStyleboxOverride("panel",box(new Color("182635"),new Color("304a5c"),8,9));parent.AddChild(panel);var column=new VBoxContainer();column.AddThemeConstantOverride("separation",5);panel.AddChild(column);var label=new Label{Text=title};label.AddThemeColorOverride("font_color",new Color("d9edf2"));label.AddThemeFontSizeOverride("font_size",14);column.AddChild(label);if(subtitle.Length>0){var note=new Label{Text=subtitle,AutowrapMode=TextServer.AutowrapMode.WordSmart};note.AddThemeColorOverride("font_color",new Color("88a5b8"));column.AddChild(note);}return column;
    }
    public void copy_transform(Control owner){var layer=main_layer(owner);if(layer==null)return;var properties=layer.Get("properties").AsGodotDictionary();owner.Set("_transform_clipboard",new Settings{["position"]=layer.Get("position"),["dimensions"]=layer.Get("dimensions"),["rotation"]=layer.Get("rotation"),["basis_x"]=Get(properties,"basis_x",Vector2.Right),["basis_y"]=Get(properties,"basis_y",Vector2.Down),["yaw_up_down"]=Get(properties,"yaw_up_down",0.0),["yaw_left_right"]=Get(properties,"yaw_left_right",0.0)});owner.Get("status").As<Label>().Text="Transform copied";}
    public void paste_transform(Control owner){var transform=owner.Get("_transform_clipboard").AsGodotDictionary();if(transform.Count==0)return;Action(owner,()=>{foreach(var id in Canvas(owner).Get("selected").AsGodotArray()){var layer=_documents.layer_for_id(Document(owner),id.AsString());if(layer==null)continue;foreach(string key in new[]{"position","dimensions","rotation"})layer.Set(key,transform[key]);var properties=layer.Get("properties").AsGodotDictionary();foreach(string key in new[]{"basis_x","basis_y","yaw_up_down","yaw_left_right"})properties[key]=transform[key];}});}
    public void match_selected_size(Control owner,bool width,bool height){var main=main_layer(owner);if(main==null)return;var target=main.Get("dimensions").AsVector2();Action(owner,()=>{foreach(var id in Canvas(owner).Get("selected").AsGodotArray()){var layer=_documents.layer_for_id(Document(owner),id.AsString());if(layer==null||layer==main)continue;var dimensions=layer.Get("dimensions").AsVector2();if(width)dimensions.X=target.X;if(height)dimensions.Y=target.Y;_documents.resize_layer(Document(owner),layer,dimensions);}});}
    public void transform_panel(Control owner)
    {
        var ui=workflow_window(owner,"Transform & align",new Vector2(680,430));var body=ui["body"].As<VBoxContainer>();var selection=panel_card(body,"Selection layout","Align one layer to the canvas, or align several layers to their shared bounds.");var align=new HFlowContainer();selection.AddChild(align);foreach(var entry in new[]{("Left","left"),("Center X","center_x"),("Right","right"),("Top","top"),("Center Y","center_y"),("Bottom","bottom")})button(owner,align,entry.Item1,Callable.From(()=>align_selected(owner,entry.Item2)),"","");button(owner,align,"Distribute X",Callable.From(()=>distribute_selected(owner,true)),"Evenly distribute three or more layers","");button(owner,align,"Distribute Y",Callable.From(()=>distribute_selected(owner,false)),"Evenly distribute three or more layers","");var match=panel_card(body,"Match & repeat","Reuse exact transforms without re-entering numbers.");var actions=new HFlowContainer();match.AddChild(actions);button(owner,actions,"Copy transform",Callable.From(()=>copy_transform(owner)),"","");button(owner,actions,"Paste transform",Callable.From(()=>paste_transform(owner)),"","");foreach(var entry in new[]{("Match main width",true,false),("Match main height",false,true),("Match complete size",true,true)})button(owner,actions,entry.Item1,Callable.From(()=>match_selected_size(owner,entry.Item2,entry.Item3)),"","");button(owner,actions,"Reset rotation / yaw",Callable.From(()=>Action(owner,()=>{foreach(var id in Canvas(owner).Get("selected").AsGodotArray()){var layer=_documents.layer_for_id(Document(owner),id.AsString());if(layer==null)continue;layer.Set("rotation",0.0);var properties=layer.Get("properties").AsGodotDictionary();properties["yaw_up_down"]=0.0;properties["yaw_left_right"]=0.0;}})),"","");ui["popup"].As<PopupPanel>().PopupCentered();
    }
    public void remember_asset(Control owner,string file){var recent=owner.Get("_recent_assets").AsGodotArray();recent.Remove(file);recent.Insert(0,file);if(recent.Count>16)recent.RemoveAt(recent.Count-1);}
    public void asset_shelf(Control owner)
    {
        var ui=workflow_window(owner,"Assets & reusable items",new Vector2(720,500));var body=ui["body"].As<VBoxContainer>();var actions=new HFlowContainer();body.AddChild(actions);button(owner,actions,"Import image…",new Callable(owner,"_choose_import"),"","");foreach(var entry in new[]{("Add text","text"),("Add shape","shape"),("Add empty layer","basic")})button(owner,actions,entry.Item1,Callable.From(()=>add_layer(owner,entry.Item2)),"","");var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};body.AddChild(scroll);var shelf=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(shelf);var recent=panel_card(shelf,"Recent project assets","Click to place an asset in the center of the current canvas.");var assets=owner.Get("_recent_assets").AsGodotArray();if(assets.Count==0)recent.AddChild(new Label{Text="Imported project images appear here automatically."});foreach(var value in assets){string file=value.AsString();button(owner,recent,file.GetFile(),Callable.From(()=>import_paths(owner,new[]{file},(Vector2)Document(owner).Get("canvas_size").AsVector2I()*.5f)),file,"image");}var styles=panel_card(shelf,"Saved styles","");var presets=owner.Get("_presets").AsGodotDictionary();foreach(var key in presets.Keys){string name=key.AsString();button(owner,styles,name,Callable.From(()=>{owner.Set("_style_clipboard",presets[name].AsGodotDictionary().Duplicate(true));paste_style(owner);}),"","");}var selections=panel_card(shelf,"Saved selections","");foreach(var key in Document(owner).Get("selections").AsGodotDictionary().Keys){string name=key.AsString();button(owner,selections,name,Callable.From(()=>{using var source=Document(owner).Get("selections").AsGodotDictionary()[name].As<Texture2D>().GetImage();Canvas(owner).Set("selection",source.Duplicate());_canvas.update_selection_preview(Canvas(owner));}),"","");}ui["popup"].As<PopupPanel>().PopupCentered();
    }
}
